using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using UnityEngine;
using GLTFast;
namespace AshinaStudio {
 public sealed class FieldWorld : IDisposable {
  public readonly List<Vector3> StagedFuel=new List<Vector3>();public Transform Root;public List<TagData> Tags=new List<TagData>();public double Length=17.55,Width=8.05;GltfImport import;public ArenaVenue Venue {get;private set;}public string Season,Layout;
  public async Task Load(string season,bool visible=true,string layout="welded"){Season=season;Layout=layout;Root=new GameObject("FRC saha "+season).transform;Root.gameObject.SetActive(visible);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="Zemin";floor.transform.SetParent(Root,false);floor.transform.position=Frc.Position(new[]{Length/2,Width/2,-.06});floor.transform.localScale=new Vector3((float)Width,.12f,(float)Length);floor.GetComponent<Renderer>().sharedMaterial=ModelLoader.Material(new Color(.14f,.18f,.23f));
   if(season=="practice"){for(int i=0;i<=17;i++)Line(new Vector3(0,.003f,i),new Vector3(-(float)Width,.003f,i),new Color(.23f,.3f,.36f),.009f);for(int i=0;i<=8;i++)Line(new Vector3(-i,.003f,0),new Vector3(-i,.003f,(float)Length),new Color(.23f,.3f,.36f),.009f);Venue=ArenaVenue.Create(Root,Length,Width,season);return;}
   string dir=Path.Combine(Application.streamingAssetsPath,"assets/fields",season);var config=JObject.Parse(File.ReadAllText(Path.Combine(dir,"config.json")));Length=(double)config["widthInches"]*.0254;Width=(double)config["heightInches"]*.0254;floor.transform.position=Frc.Position(new[]{Length/2,Width/2,-.06});floor.transform.localScale=new Vector3((float)Width,.12f,(float)Length);
   var model=new GameObject("Resmi saha modeli").transform;model.SetParent(Root,false);model.localPosition=Frc.Position(new[]{Length/2,Width/2,0});model.localRotation=Frc.Rotation(new[]{0.0,0,180});var configRoot=new GameObject("Model dönüşümü").transform;configRoot.SetParent(model,false);Quaternion rotation=Quaternion.identity;foreach(var r in config["rotations"]??new JArray()){var angles=new double[3];angles[(string)r["axis"]=="x"?0:(string)r["axis"]=="y"?1:2]=(double)r["degrees"];rotation=Frc.Rotation(angles)*rotation;}configRoot.localRotation=rotation;if(config["position"] is JArray pos)configRoot.localPosition=Frc.Position(pos.ToObject<double[]>());var basis=new GameObject("GLB eksenleri").transform;basis.SetParent(configRoot,false);basis.localRotation=Quaternion.LookRotation(Vector3.up,Vector3.left);import=new GltfImport();if(!await import.LoadGltfBinary(File.ReadAllBytes(Path.Combine(dir,"model.glb"))))throw new Exception("Saha modeli yüklenemedi.");if(!await import.InstantiateMainSceneAsync(basis))throw new Exception("Saha oluşturulamadı.");
   // The official carpet is the visible floor. Keep the fallback collider below it.
   floor.GetComponent<Renderer>().enabled=false;floor.transform.position+=Vector3.down*.025f;
   string fuelLayout=Path.Combine(dir,"fuel-layout.json");if(File.Exists(fuelLayout))foreach(var position in JArray.Parse(File.ReadAllText(fuelLayout)))StagedFuel.Add(Frc.Position(position.ToObject<double[]>()));
   var staged=new HashSet<string>((config["gamePieces"]??new JArray()).SelectMany(x=>x["stagedObjects"]??new JArray()).Select(x=>Canonical((string)x)));foreach(var t in basis.GetComponentsInChildren<Transform>(true))if(staged.Contains(Canonical(t.name)))t.gameObject.SetActive(false);
   foreach(var renderer in basis.GetComponentsInChildren<Renderer>())foreach(var material in renderer.sharedMaterials){if(material==null)continue;if(material.HasProperty("_Metallic"))material.SetFloat("_Metallic",.12f);if(material.HasProperty("_Glossiness"))material.SetFloat("_Glossiness",.25f);}
   if(season=="2025")FieldDynamics.CreateCages(basis,Root);
   string binary=Path.Combine(dir,"collision.bin");if(File.Exists(binary)){using(var reader=new BinaryReader(File.OpenRead(binary))){int nv=reader.ReadInt32(),ni=reader.ReadInt32();if(nv>2000000||ni>6000000)throw new Exception("Saha geometrisi sınırı.");var vertices=new Vector3[nv];var indices=new int[ni];for(int i=0;i<nv;i++)vertices[i]=Frc.Position(new[]{(double)reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle()});for(int i=0;i<ni;i+=3){indices[i]=reader.ReadInt32();indices[i+2]=reader.ReadInt32();indices[i+1]=reader.ReadInt32();}CollisionChunks(vertices,indices);}}
   string filename=season=="2024"?"2024-crescendo.json":season=="2025"?"2025-reefscape-"+layout+".json":"2026-rebuilt-"+layout+".json";var data=JObject.Parse(File.ReadAllText(Path.Combine(Application.streamingAssetsPath,"assets/tags",filename)));foreach(var tag in data["tags"]){var p=tag["pose"]["translation"];var q=tag["pose"]["rotation"]["quaternion"];var t=new TagData{Id=(int)tag["ID"],Position=Frc.Position(new[]{(double)p["x"],(double)p["y"],(double)p["z"]}),Rotation=Frc.QuaternionData((double)q["X"],(double)q["Y"],(double)q["Z"],(double)q["W"])};Tags.Add(t);var plate=GameObject.CreatePrimitive(PrimitiveType.Quad);plate.name="AprilTag "+t.Id;plate.transform.SetParent(Root,false);plate.transform.position=t.Position+(t.Rotation*Vector3.forward)*.006f;plate.transform.rotation=t.Rotation*Quaternion.Euler(0,180,0);plate.transform.localScale=Vector3.one*.205f;Lifetime.Destroy(plate.GetComponent<Collider>());var texture=new Texture2D(2,2);texture.LoadImage(File.ReadAllBytes(Path.Combine(Application.streamingAssetsPath,"assets/tags/images",t.Id+".png")));texture.filterMode=FilterMode.Point;var material=new Material(Shader.Find("Unlit/Texture"));material.mainTexture=texture;plate.GetComponent<Renderer>().sharedMaterial=material;}
   Venue=ArenaVenue.Create(Root,Length,Width,season);
  }
  public float GroundHeight(Vector3 position){
   var hits=Physics.RaycastAll(new Vector3(position.x,.55f,position.z),Vector3.down,1,1,QueryTriggerInteraction.Ignore);
   float height=0;foreach(var hit in hits)if(hit.normal.y>.65f&&hit.point.y<=.35f)height=Mathf.Max(height,hit.point.y);return height;
  }
  static string Canonical(string name)=>System.Text.RegularExpressions.Regex.Replace(System.Text.RegularExpressions.Regex.Replace(name.ToLowerInvariant(),@"[^a-z0-9]+","_").Trim('_'),@"_\d+$","");
  void CollisionChunks(Vector3[] vertices,int[] indices){for(int start=0;start<indices.Length;start+=450000){int count=Math.Min(450000,indices.Length-start);var remap=new Dictionary<int,int>();var chunkVertices=new List<Vector3>();var chunkIndices=new int[count];for(int i=0;i<count;i++){int old=indices[start+i];if(!remap.TryGetValue(old,out var index)){index=chunkVertices.Count;remap[old]=index;chunkVertices.Add(vertices[old]);}chunkIndices[i]=index;}var collider=new GameObject("Saha çarpışma yüzeyi "+start);collider.transform.SetParent(Root,false);collider.AddComponent<MeshCollider>().sharedMesh=ModelLoader.Mesh(chunkVertices.ToArray(),chunkIndices);}}
  void Line(Vector3 a,Vector3 b,Color color,float width){var go=new GameObject("Saha çizgisi");go.transform.SetParent(Root,false);var line=go.AddComponent<LineRenderer>();line.positionCount=2;line.SetPositions(new[]{a,b});line.startWidth=line.endWidth=width;line.material=new Material(Shader.Find("Sprites/Default")){color=color};line.startColor=line.endColor=color;}
  public void Dispose(){if(Root!=null)Root.gameObject.SetActive(false);Venue?.Dispose();import?.Dispose();if(Root!=null)Lifetime.Destroy(Root.gameObject);Tags.Clear();}
 }
 public class TagData {public int Id;public Vector3 Position;public Quaternion Rotation;}
 public class VisionFrame {public long Sequence;public float Captured,Latency;public double[] Pose,CameraPose;public List<SeenTag> Seen=new List<SeenTag>();}
 public class SeenTag {public int Id;public double Tx,Ty,Area,Distance;public double[] CameraToTarget;}
 public static class Vision {
  static long sequence;public static double[] Transform(Vector3 p,Quaternion q){var position=Frc.Position(p);return new[]{position[0],position[1],position[2],(double)q.w,-q.z,q.x,-q.y};}

  public static VisionFrame Detect(CameraData camera,Transform mount,FieldWorld field,double[] pose){var frame=new VisionFrame{Captured=Time.realtimeSinceStartup,Latency=(float)camera.latency,Pose=(double[])pose.Clone()};var origin=mount.TransformPoint(Frc.Position(camera.position));var rotation=mount.rotation*Frc.Rotation(camera.rotation);frame.Sequence=++sequence;frame.CameraPose=Transform(origin,rotation);var inverse=Quaternion.Inverse(rotation);foreach(var tag in field.Tags){var local=inverse*(tag.Position-origin);double distance=local.magnitude,yaw=Math.Atan2(-local.x,local.z)*180/Math.PI,pitch=Math.Atan2(local.y,Math.Sqrt(local.z*local.z+local.x*local.x))*180/Math.PI;if(local.z<=0||distance>camera.range||Math.Abs(yaw)>camera.hfov/2||Math.Abs(pitch)>camera.vfov/2)continue;if(Vector3.Dot(tag.Rotation*Vector3.forward,origin-tag.Position)<=0)continue;if(Physics.Raycast(origin,(tag.Position-origin).normalized,(float)distance-.1f,1,QueryTriggerInteraction.Ignore))continue;frame.Seen.Add(new SeenTag{CameraToTarget=Transform(local,inverse*tag.Rotation),Id=tag.Id,Tx=-yaw,Ty=pitch,Distance=distance,Area=Math.Min(100,100*.165*.165/(4*distance*distance*Math.Tan(camera.hfov*Math.PI/360)*Math.Tan(camera.vfov*Math.PI/360)))});}frame.Seen.Sort((a,b)=>a.Distance.CompareTo(b.Distance));return frame;}
 }
}



